def group_by_first_char(words: list[str]) -> dict[str, list[str]]:
    groups = {}
    for word in words:
        if not word:
            continue
        first_char = word[0]
        if first_char in groups:
            groups[first_char].append(word)
        else:
            groups[first_char] = [word]
    return groups
